CREATE TABLE public.equipe_membros (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE, ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.equipe_membros TO authenticated;
GRANT ALL ON public.equipe_membros TO service_role;
ALTER TABLE public.equipe_membros ENABLE ROW LEVEL SECURITY;
CREATE POLICY equipe_admin ON public.equipe_membros FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY equipe_self ON public.equipe_membros FOR SELECT TO authenticated USING (user_id=auth.uid());
ALTER TABLE public.leads ADD COLUMN cliente_id uuid REFERENCES public.clientes(id), ADD COLUMN tipo_pessoa public.tipo_pessoa_enum;
ALTER TABLE public.lancamentos ADD COLUMN recorrente boolean NOT NULL DEFAULT false, ADD COLUMN parcela_atual integer, ADD COLUMN parcelas_total integer;
ALTER TABLE public.pf_transacoes ADD COLUMN parcela_atual integer, ADD COLUMN parcelas_total integer;
CREATE OR REPLACE FUNCTION public.can_manage_cliente(_user_id uuid,_cliente_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=_cliente_id AND (c.user_id=_user_id OR public.has_role(_user_id,'admin') OR (c.responsavel_id=_user_id AND EXISTS(SELECT 1 FROM public.equipe_membros m WHERE m.user_id=_user_id AND m.ativo)))) $$;
REVOKE ALL ON FUNCTION public.can_manage_cliente(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_manage_cliente(uuid,uuid) TO authenticated,service_role;
CREATE POLICY clientes_equipe ON public.clientes FOR SELECT TO authenticated USING (public.can_manage_cliente(auth.uid(),id));
CREATE POLICY clientes_equipe_update ON public.clientes FOR UPDATE TO authenticated USING (public.can_manage_cliente(auth.uid(),id)) WITH CHECK (public.can_manage_cliente(auth.uid(),id));
CREATE OR REPLACE FUNCTION private.has_cliente_access(_user_id uuid,_cliente_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.can_manage_cliente(_user_id,_cliente_id) OR EXISTS(SELECT 1 FROM public.clientes WHERE id=_cliente_id AND cliente_user_id=_user_id) $$;
CREATE POLICY analises_equipe ON public.cliente_analises FOR ALL TO authenticated USING (public.can_manage_cliente(auth.uid(),cliente_id)) WITH CHECK (public.can_manage_cliente(auth.uid(),cliente_id));
CREATE POLICY anamnese_equipe ON public.cliente_anamnese FOR ALL TO authenticated USING (public.can_manage_cliente(auth.uid(),cliente_id)) WITH CHECK (public.can_manage_cliente(auth.uid(),cliente_id));
CREATE POLICY eventos_equipe ON public.cliente_eventos FOR ALL TO authenticated USING (public.can_manage_cliente(auth.uid(),cliente_id)) WITH CHECK (public.can_manage_cliente(auth.uid(),cliente_id));
CREATE POLICY lancamentos_equipe ON public.lancamentos FOR ALL TO authenticated USING (cliente_id IS NOT NULL AND public.can_manage_cliente(auth.uid(),cliente_id)) WITH CHECK (cliente_id IS NOT NULL AND public.can_manage_cliente(auth.uid(),cliente_id));
CREATE POLICY tarefas_equipe ON public.tarefas FOR ALL TO authenticated USING (cliente_id IS NOT NULL AND public.can_manage_cliente(auth.uid(),cliente_id)) WITH CHECK (cliente_id IS NOT NULL AND public.can_manage_cliente(auth.uid(),cliente_id));
CREATE POLICY agenda_equipe ON public.agendamentos FOR ALL TO authenticated USING (cliente_id IS NOT NULL AND public.can_manage_cliente(auth.uid(),cliente_id)) WITH CHECK (cliente_id IS NOT NULL AND public.can_manage_cliente(auth.uid(),cliente_id));
CREATE POLICY leads_admin_only ON public.leads AS RESTRICTIVE FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.cliente_analise_versoes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), analise_id uuid NOT NULL REFERENCES public.cliente_analises(id), cliente_id uuid NOT NULL REFERENCES public.clientes(id), conteudo text NOT NULL, titulo text NOT NULL, revisado boolean NOT NULL, revisado_por uuid, revisado_em timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.cliente_analise_versoes TO authenticated;
GRANT ALL ON public.cliente_analise_versoes TO service_role;
ALTER TABLE public.cliente_analise_versoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY versoes_educadora ON public.cliente_analise_versoes FOR SELECT TO authenticated USING (public.can_manage_cliente(auth.uid(),cliente_id));
CREATE OR REPLACE FUNCTION public.audit_analise_revision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN INSERT INTO public.cliente_analise_versoes(analise_id,cliente_id,conteudo,titulo,revisado,revisado_por,revisado_em) VALUES(OLD.id,OLD.cliente_id,OLD.conteudo,OLD.titulo,OLD.revisado,OLD.revisado_por,OLD.revisado_em); IF NEW.conteudo IS DISTINCT FROM OLD.conteudo OR NEW.titulo IS DISTINCT FROM OLD.titulo THEN NEW.revisado=false; NEW.revisado_por=null; NEW.revisado_em=null; END IF; END IF; IF NEW.revisado THEN IF auth.uid() IS NOT NULL AND NOT public.can_manage_cliente(auth.uid(),NEW.cliente_id) THEN RAISE EXCEPTION 'Somente a educadora pode aprovar esta análise'; END IF; NEW.revisado_por=coalesce(auth.uid(),NEW.revisado_por); NEW.revisado_em=now(); IF NEW.revisado_por IS NULL THEN RAISE EXCEPTION 'Responsável pela revisão é obrigatório'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER audit_analise_revision BEFORE INSERT OR UPDATE ON public.cliente_analises FOR EACH ROW EXECUTE FUNCTION public.audit_analise_revision();
CREATE OR REPLACE FUNCTION public.workspace_access(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'admin') OR public.has_active_subscription(_user_id,'live') OR EXISTS(SELECT 1 FROM public.profiles WHERE user_id=_user_id AND trial_ends_at>now()) OR EXISTS(SELECT 1 FROM public.clientes c WHERE c.cliente_user_id=_user_id AND (public.has_role(c.user_id,'admin') OR public.has_active_subscription(c.user_id,'live') OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.user_id=c.user_id AND p.trial_ends_at>now()))) $$;
REVOKE ALL ON FUNCTION public.workspace_access(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.workspace_access(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.protect_profile_billing() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL THEN IF TG_OP='INSERT' THEN NEW.plano='trial'; NEW.trial_ends_at=now()+interval '7 days'; ELSE IF NEW.plano IS DISTINCT FROM OLD.plano OR NEW.trial_ends_at IS DISTINCT FROM OLD.trial_ends_at OR NEW.user_id IS DISTINCT FROM OLD.user_id THEN RAISE EXCEPTION 'Plano e avaliação são gerenciados pelo sistema de pagamentos'; END IF; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_profile_billing BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_profile_billing();
CREATE OR REPLACE FUNCTION public.enforce_workspace_access() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.workspace_access(auth.uid()) THEN RAISE EXCEPTION 'Sua avaliação terminou. Escolha um plano para continuar.'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['clientes','lancamentos','tarefas','cliente_anamnese','cliente_analises','cliente_eventos','pf_transacoes','pf_dividas','pf_metas_pessoais','pf_limites_categoria','pf_patrimonio','pf_notas_mensais','produtos','contratos','pedidos_venda','ordens_compra','ordens_servico','fornecedores','contas_pagar','contas_receber','fluxo_caixa','metas','plano_contas','centros_custo','funcionarios','adiantamentos','notas_fiscais','apuracao_impostos','contas_bancarias','estoque_movimentacoes','extrato_bancario'] LOOP EXECUTE format('CREATE TRIGGER enforce_workspace_access BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.enforce_workspace_access()',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.convert_lead_to_cliente(_lead_id uuid,_tipo public.tipo_pessoa_enum) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE l public.leads; cid uuid; BEGIN SELECT * INTO l FROM public.leads WHERE id=_lead_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Contato não encontrado'; END IF; IF l.cliente_id IS NOT NULL THEN RETURN l.cliente_id; END IF; INSERT INTO public.clientes(user_id,nome,email,telefone,observacoes,tipo_pessoa,responsavel_id) VALUES(auth.uid(),l.nome,l.email,l.telefone,l.observacoes,_tipo,auth.uid()) RETURNING id INTO cid; UPDATE public.leads SET cliente_id=cid,tipo_pessoa=_tipo,etapa='cliente',status='cliente' WHERE id=l.id; INSERT INTO public.cliente_eventos(cliente_id,user_id,tipo,titulo,descricao) VALUES(cid,auth.uid(),'cadastro','Contato convertido em cliente',coalesce(l.origem,'Funil de captação')); RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.convert_lead_to_cliente(uuid,public.tipo_pessoa_enum) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.convert_lead_to_cliente(uuid,public.tipo_pessoa_enum) TO authenticated;
CREATE OR REPLACE FUNCTION public.reserve_appointment_lock() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status='cancelado' THEN RETURN NEW; END IF; IF NEW.duracao_min<15 OR NEW.duracao_min>480 THEN RAISE EXCEPTION 'Duração inválida'; END IF; PERFORM pg_advisory_xact_lock(hashtext(coalesce(NEW.user_id::text,'public-agenda'))); IF EXISTS(SELECT 1 FROM public.agendamentos a WHERE a.id<>NEW.id AND a.status<>'cancelado' AND a.user_id IS NOT DISTINCT FROM NEW.user_id AND tstzrange(a.inicio,a.inicio+make_interval(mins=>a.duracao_min),'[)') && tstzrange(NEW.inicio,NEW.inicio+make_interval(mins=>NEW.duracao_min),'[)')) THEN RAISE EXCEPTION 'Horário já ocupado. Escolha outro horário.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER reserve_appointment_lock BEFORE INSERT OR UPDATE OF inicio,duracao_min,status ON public.agendamentos FOR EACH ROW EXECUTE FUNCTION public.reserve_appointment_lock();